objective": "Baik ėjimą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Auksas nepersikelia. Spausk „Baigti ėjimą\".", "voiceId": "l1-s16", "voiceText": "Daugiau aukso neturi, tad baik ėjimą. Prisimink — auksas nepersikelia. Spausk „Baigti ėjimą\"."}], "highlight": [{"kind": "button", "id": "end-turn"}], "arrowTo": {"kind": "button", "id": "end-turn"}, "arrowStyle": "pulse", "allow": [{"kind": "end-turn"}], "wrongHint": "Spausk paryškintą „Baigti ėjimą\" mygtuką.", "complete": {"on": "event", "eventType": "endTurn", "side": "you"}}, {"id": "enemy-turn", "objective": "Stebėk priešą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Dabar eina priešininkas. Stebėk.", "voiceId": "l1-s17", "voiceText": "Dabar eina priešininkas. Stebėk. Kartais geriausia pamoka — žiūrėti, ką daro priešas."}], "enemyScript": [{"type": "play", "cardName": "Goblinas žvalgas"}, {"type": "endTurn"}], "complete": {"on": "enemyTurnDone"}}, {"id": "gold-grows", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Matai? Antras ėjimas — du šimtai aukso.", "voiceId": "l1-s18", "voiceText": "Matai? Antras ėjimas — du šimtai aukso. Kas ėjimą vis daugiau. Vėliau galėsi žaisti po kelias kortas iš karto."}], "highlight": [{"kind": "anchor", "anchor": "gold"}], "arrowTo": {"kind": "anchor", "anchor": "gold"}, "arrowStyle": "pulse", "zoom": {"kind": "anchor", "anchor": "gold"}, "zoomLevel": 2.2, "complete": {"on": "next"}}, {"id": "play-second", "objective": "Sužaisk antrą padarą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Sužaisk dar vieną padarą — dabar aukso užtenka.", "voiceId": "sys-good-2", "voiceText": "Būtent taip."}], "highlight": [{"kind": "handCard", "cardName": "Ida"}], "arrowFrom": {"kind": "handCard", "cardName": "Ida"}, "arrowTo": {"kind": "anchor", "anchor": "units-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-unit", "cardName": "Ida"}], "complete": {"on": "event", "eventType": "play", "side": "you", "cardName": "Ida"}}, {"id": "l1-outro", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Užtenka pirmam kartui. Kitoje pamokoje — kaip kautis.", "voiceId": "l1-s19", "voiceText": "Užtenka pirmam kartui. Įsimink: auksas kvėpuoja, kortos kainuoja, padarai serga iškvietimo liga. Kitoje pamokoje — kaip kautis. Eik pailsėk, mokiny."}], "complete": {"on": "next"}}]}$cfg$::jsonb, updated_at = now() where seed_key = 'tut-v3-l1';
