om": {"kind": "unit", "side": "you", "cardName": "Ida"}, "complete": {"on": "next"}}, {"id": "retaliation-rule", "objective": "Suprask mainus", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kai puoli padarą — jis kerta atgal. Kiekviena ataka yra mainai.", "voiceId": "l2-s04", "voiceText": "Bet dabar klausyk atidžiai, nes čia žūsta naujokai. Kai puoli padarą — jis kerta atgal. Tu gauni jo atakos žalą, nesvarbu, ar jis išgyvena. Kiekviena ataka yra mainai."}], "highlight": [{"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}], "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}, "arrowStyle": "pulse", "zoom": {"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}, "complete": {"on": "next"}}, {"id": "trade-math", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Jo 3/3 prieš tavo 3/4: jis žus, tau liks viena gyvybė. Visada skaičiuok.", "voiceId": "l2-s05", "voiceText": "Pažvelk: jo ataka trys, gyvybės trys. Tavo — trys ir keturi. Pulsi — jis žus, bet tau liks viena gyvybė. Verta? Dažnai — taip. Bet visada skaičiuok."}], "highlight": [{"kind": "unit", "side": "you", "cardName": "Gisela"}, {"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}], "zoom": {"kind": "unit", "side": "you", "cardName": "Gisela"}, "complete": {"on": "next"}}, {"id": "trade-do", "objective": "Atlik mainus", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Pulk. Pajusk mainus savo kailiu.", "voiceId": "l2-s06", "voiceText": "Pulk. Pajusk mainus savo kailiu."}], "highlight": [{"kind": "unit", "side": "you", "cardName": "Gisela"}, {"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}], "arrowFrom": {"kind": "unit", "side": "you", "cardName": "Gisela"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}, "arrowStyle": "drag-path", "allow": [{"kind": "attack-unit", "targetName": "Zombis klajoklis"}], "complete": {"on": "event", "eventType": "attack", "side": "you"}}, {"id": "zmk-intro", "objective": "Pažink Žalos Modifikavimo Kortas", "apply": {"enableZmk": true}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kiekvieną kartą, kai kertama žala, traukiama viena ŽMK.", "voiceId": "l2-s07", "voiceText": "O dabar... Žalos Modifikavimo Kortos. Likimas. Kiekvieną kartą, kai kertama žala, traukiama viena šių kortų."}], "highlight": [{"kind": "anchor", "anchor": "zmk"}], "arrowTo": {"kind": "anchor", "anchor": "zmk"}, "arrowStyle": "pulse", "zoom": {"kind": "anchor", "anchor": "zmk"}, "zoomLevel": 2.2, "complete": {"on": "next"}}, {"id": "zmk-values", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "+ didina, − mažina, ×2 dvigubina, ×0 — smūgis nueina vėjais.", "voiceId": "l2-s08", "voiceText": "Pliusas — žala didesnė. Minusas — mažesnė. Kryžius du — žala dviguba. O kryžius nulis... smūgis nueina vėjais. Todėl Ravenof'e net tikras kirtis niekada nėra tikras."}], "highlight": [{"kind": "anchor", "anchor": "zmk"}], "zoom": {"kind": "anchor", "anchor": "zmk"}, "zoomLevel": 2.2, "complete": {"on": "next"}}, {"id": "zmk-live", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Nuo šiol likimo kortos maišosi į kiekvieną tavo smūgį.", "voiceId": "l2-s09", "voiceText": "Nuo šiol likimo kortos maišosi į kiekvieną tavo smūgį. Priprask prie netikrumo — jis čia amžinas."}], "complete": {"on": "next"}}, {"id": "go-face", "objective": "Kirsk tiesiai priešui", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kai kelias laisvas — tempk padarą ant priešo herbo.", "voiceId": "l2-s10", "voiceText": "Kai priešo lenta tuščia — kirsk tiesiai į veidą. Tempk padarą ant priešo herbo. Tai kelias į pergalę."}], "highlight": [{"kind": "unit", "side": "you", "cardName": "Hokieg’as"}, {"kind": "anchor", "anchor": "hp-ai"}], "arrowFrom": {"kind": "unit", "side": "you", "cardName": "Hokieg’as"}, "arrowTo": {"kind": "anchor", "anchor": "hp-ai"}, "arrowStyle": "drag-path", "allow": [{"kind": "attack-face"}], "wrongHint": "Tempk padarą ant PRIEŠO herbo viršuje.", "complete": {"on": "event", "eventType": "attack", "side": "you"}}, {"id": "end-turn", "objective": "Baik ėjimą ir pajusk priešo smūgį", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Baik ėjimą. Priešo ėjimas — stebėk.", "voiceId": "sys-turn-enemy", "voiceText": "Priešo ėjimas. Stebėk."}], "highlight": [{"kind": "button", "id": "end-turn"}], "arrowTo": {"kind": "button", "id": "end-turn"}, "arrowStyle": "pulse", "allow": [{"kind": "end-turn"}], "complete": {"on": "event", "eventType": "endTurn", "side": "you"}}, {"id": "enemy-hits", "enemyScript": [{"type": "attack", "attackerCard": "Wrosxa", "face": true}, {"type": "endTurn"}], "complete": {"on": "enemyTurnDone"}}, {"id": "pain-lesson", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Skauda? Gerai. Palikta priešo lenta artina TAVO pabaigą.", "voiceId": "l2-s11", "voiceText": "Skauda? Gerai. Dabar žinai, ką jaučia priešas. Žala veidan artina pabaigą — bet palikta priešo lenta artina tavo pabaigą. Balansas, mokiny."}], "highlight": [{"kind": "anchor", "anchor": "hp-you"}], "zoom": {"kind": "anchor", "anchor": "hp-you"}, "complete": {"on": "next"}}, {"id": "finish", "objective": "Užbaik priešą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Priešo gyvybės senka. Užbaik.", "voiceId": "l2-s12", "voiceText": "Priešo gyvybės senka. Užbaik. Nukalk jas iki nulio."}], "allow": [{"kind": "attack-any"}, {"kind": "play-unit"}, {"kind": "end-turn"}], "complete": {"on": "win"}}, {"id": "victory", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Pergalė! Ravenof tavimi patenkintas.", "voiceId": "sys-victory", "voiceText": "Pergalė! Ravenof tavimi patenkintas."}], "complete": {"on": "next"}}]}$cfg$::jsonb, updated_at = now() where seed_key = 'tut-v3-l2';
update public.tutorial_lessons set config = $cfg${"guideName": "Senasis Korvas", "setup": {"disableZmk": true, "player": {"gold": 900, "board": ["Ida", "Gisela"], "hand": ["Stingdantis kristalas", "Tornadas", "Paslėpta galia", "Šviesos palaiminimas"], "deck": ["Piratas žvalgas", "Hokieg’as", "Ida"]}, "enemy": {"hp": 8, "board": ["Hikage", "Zombis klajoklis", "Goblinas žvalgas"], "deck": ["Hikage", "Goblinas žvalgas"]}}, "steps": [{"id": "intro", "objective": "Išmok magiją", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kardai — ne vienintelis kelias. Šiandien — magija.", "voiceId": "l3-s01", "voiceText": "Kardai — ne vienintelis kelias. Šiandien — magija."}], "complete": {"on": "next"}}, {"id": "targeted-spell", "objective": "Mesk burtą į taikinį", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Burtai suveikia iškart ir gula į kapinyną. Tempk jį ant priešo padaro.", "voiceId": "l3-s02", "voiceText": "Burtai suveikia iškart ir gula į kapinyną. Vieni reikalauja taikinio, kiti — ne. Šis reikalauja. Tempk jį ant priešo padaro."}], "highlight": [{"kind": "handCard", "cardName": "Stingdantis kristalas"}, {"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}], "arrowFrom": {"kind": "handCard", "cardName": "Stingdantis kristalas"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-spell", "cardName": "Stingdantis kristalas"}], "complete": {"on": "event", "eventType": "spell", "side": "you", "cardName": "Stingdantis kristalas"}}, {"id": "docked-preview", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Tempiant kortos aprašymas lieka kairėje — skaityk jį renkantis taikinį.", "voiceId": "l3-s03", "voiceText": "Pastebėjai? Kol tempi, kortos aprašymas lieka kairiajame krašte. Skaityk jį rinkdamasis taikinį — tekstas visada svarbiau už atmintį."}], "complete": {"on": "next"}}, {"id": "aoe", "objective": "Paleisk audrą (AOE)", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Šis burtas taikinių nesirenka — kerta VISUS priešo padarus.", "voiceId": "l3-s04", "voiceText": "O šis burtas — audra. Taikinių nesirenka: kerta visus priešo padarus iš karto. Tokie burtai brangūs, bet apverčia kovą. Paleisk."}], "highlight": [{"kind": "handCard", "cardName": "Tornadas"}, {"kind": "anchor", "anchor": "units-ai"}], "arrowFrom": {"kind": "handCard", "cardName": "Tornadas"}, "arrowTo": {"kind": "anchor", "anchor": "units-ai"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-spell", "cardName": "Tornadas"}], "complete": {"on": "event", "eventType": "spell", "side": "you", "cardName": "Tornadas"}}, {"id": "aoe-note", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Gražu. Bet audros netaškyk tuščiai lentai.", "voiceId": "l3-s05", "voiceText": "Gražu, tiesa? Bet įsimink — audros nešvaisto tuščiai lentai. Lauk, kol priešas išsistatys."}], "complete": {"on": "next"}}, {"id": "reaction-intro", "objective": "Paruošk spąstus", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Reakcijos žaidžiamos UŽVERSTOS. Priešas jų nemato.", "voiceId": "l3-s06", "voiceText": "Dabar — spąstai. Reakcijos. Jos žaidžiamos užverstos į šitą zoną. Priešas jų nemato. Ir nežino, kada suveiks."}], "highlight": [{"kind": "anchor", "anchor": "reactions-you"}], "arrowTo": {"kind": "anchor", "anchor": "reactions-you"}, "arrowStyle": "pulse", "zoom": {"kind": "anchor", "anchor": "reactions-you"}, "complete": {"on": "next"}}, {"id": "reaction-set", "objective": "Padėk reakciją", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Padėk reakciją. Tegul laukia tamsoje.", "voiceId": "l3-s07", "voiceText": "Padėk reakciją. Tegul laukia tamsoje."}], "highlight": [{"kind": "handCard", "cardName": "Paslėpta galia"}, {"kind": "anchor", "anchor": "reactions-you"}], "arrowFrom": {"kind": "handCard", "cardName": "Paslėpta galia"}, "arrowTo": {"kind": "anchor", "anchor": "reactions-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-any", "cardName": "Paslėpta galia"}], "complete": {"on": "event", "eventType": "reactionSet", "side": "you"}}, {"id": "wait-for-trap", "objective": "Baik ėjimą ir lauk", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Dabar lauk. Priešas puls. Ir tada...", "voiceId": "l3-s08", "voiceText": "Dabar lauk. Priešas puls. Ir tada..."}], "highlight": [{"kind": "button", "id": "end-turn"}], "arrowTo": {"kind": "button", "id": "end-turn"}, "arrowStyle": "pulse", "allow": [{"kind": "end-turn"}], "complete": {"on": "event", "eventType": "endTurn", "side": "you"}}, {"id": "trap-springs", "enemyScript": [{"type": "play", "cardName": "Hikage"}, {"type": "attack", "attackerCard": "Hikage", "targetCard": "Ida"}, {"type": "endTurn"}], "complete": {"on": "enemyTurnDone"}}, {"id": "trap-explain", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "ŠTAI! Reakcija smogė tam, kuris ją pažadino.", "voiceId": "l3-s09", "voiceText": "Štai! Spąstai užsitrenkė! Reakcija smogė tam, kuris ją pažadino. Priešas dabar dukart pagalvos prieš puldamas."}], "highlight": [{"kind": "anchor", "anchor": "reactions-you"}], "complete": {"on": "next"}}, {"id": "finish", "objective": "Užbaik kovą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Reakcijos — tavo nematoma ranka. Užbaik kovą, mokiny.", "voiceId": "l3-s10", "voiceText": "Reakcijos — tavo nematoma ranka. Gera kaladė visada turi bent porą. Užbaik kovą, mokiny."}], "allow": [{"kind": "attack-any"}, {"kind": "play-unit"}, {"kind": "play-spell"}, {"kind": "end-turn"}], "complete": {"on": "win"}}, {"id": "victory", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Pergalė! Ravenof tavimi patenkintas.", "voiceId": "sys-victory", "voiceText": "Pergalė! Ravenof tavimi patenkintas."}], "complete": {"on": "next"}}]}$cfg$::jsonb, updated_at = now() where seed_key = 'tut-v3-l3';
update public.tutorial_lessons set config = $cfg${"guideName": "Senasis Korvas", "setup": {"disableZmk": true, "player": {"gold": 1000, "board": ["Gisela", "Hokieg’as"], "hand": ["Archimagas Lisarijus|1", "Piratas žvalgas", "Ida", "Archimagas Lisarijus|2", "Piratas žvalgas", "Hokieg’as"], "deck": ["Ida", "Gisela", "Piratas žvalgas"]}, "enemy": {"hp": 16, "board": ["Hikage"], "hand": ["Goblinas žvalgas", "Hikage"], "deck": ["Zombis klajoklis", "Naotsuo", "Hikage", "Goblinas žvalgas", "Zombis klajoklis"]}}, "enemyAi": "easy", "steps": [{"id": "intro", "objective": "Pašauk čempioną", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Šiandien ypatinga diena. Šiandien tu pašauksi ČEMPIONĄ.", "voiceId": "l4-s01", "voiceText": "Šiandien ypatinga diena. Šiandien tu pašauksi ČEMPIONĄ."}], "complete": {"on": "next"}}, {"id": "tribute-rule", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Čempionas reikalauja AUKOS: dvi kortos iš rankos ARBA vienas padaras nuo lentos.", "voiceId": "l4-s02", "voiceText": "Čempionas — ne eilinis karys. Jis reikalauja aukos: dvi kortos iš rankos arba vienas tavo padaras nuo lentos. Rinkis atsargiai... arba atšauk, jei suabejosi — mygtukas apačioje."}], "showCard": "Archimagas Lisarijus", "complete": {"on": "next"}}, {"id": "summon-champ", "objective": "Paaukok dvi kortas ir iškviesk čempioną", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Paaukok dvi kortas. Tegul ateina.", "voiceId": "l4-s03", "voiceText": "Paaukok dvi kortas. Tegul ateina."}], "highlight": [{"kind": "handCard", "cardName": "Archimagas Lisarijus"}], "arrowFrom": {"kind": "handCard", "cardName": "Archimagas Lisarijus"}, "arrowTo": {"kind": "anchor", "anchor": "units-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-any", "cardName": "Archimagas Lisarijus"}], "wrongHint": "Pradėk nuo paryškintos čempiono kortos — tada paaukok 2 kortas iš rankos arba padarą nuo lentos.", "complete": {"on": "event", "eventType": "champion", "side": "you"}}, {"id": "phases", "objective": "Pažvelk į fazes", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Žvaigždės po juo — FAZĖS. Pirma fazė — tik pradžia.", "voiceId": "l4-s04", "voiceText": "Štai jis. Pažvelk į žvaigždes po juo — tai fazės. Pirma fazė — tik pradžia."}], "highlight": [{"kind": "anchor", "anchor": "champion-you"}], "arrowTo": {"kind": "anchor", "anchor": "champion-you"}, "arrowStyle": "pulse", "zoom": {"kind": "anchor", "anchor": "champion-you"}, "zoomLevel": 2, "complete": {"on": "next"}}, {"id": "upgrade", "objective": "Pakelk čempioną į antrą fazę", "apply": {"goldYou": 1000}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Antra fazė — ATSKIRA korta: sumoki auksą ir vėl aukoji. Pirma fazė privalo stovėti lentoje.", "voiceId": "l4-s05", "voiceText": "Čempionas auga ne pats. Antra fazė — atskira korta iš rankos: sumoki jos auksą ir vėl paaukoji. Bet įsidėmėk: pirmoji fazė privalo stovėti lentoje, kitaip antroji neateis. Trečioji — lygiai taip pat. Sužaisk antrąją fazę."}], "highlight": [{"kind": "handCard", "cardName": "Archimagas Lisarijus"}], "arrowFrom": {"kind": "handCard", "cardName": "Archimagas Lisarijus"}, "arrowTo": {"kind": "anchor", "anchor": "champion-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "upgrade-champion"}, {"kind": "play-any", "cardName": "Archimagas Lisarijus"}], "wrongHint": "Sužaisk antros fazės kortą ir paaukok dvi kortas iš rankos.", "complete": {"on": "event", "eventType": "evolve", "side": "you"}}, {"id": "skills", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Pirmas įgūdis — nuo pradžių, antras — nuo antros fazės, trečias — pilnai užaugus.", "voiceId": "l4-s06", "voiceText": "Dabar jo galios. Pirmas įgūdis atrakintas nuo pradžių. Antras — nuo antros fazės. Trečias — tik pilnai užaugus. Užrakintos galios pilkos — jų laikas dar ateis."}], "highlight": [{"kind": "anchor", "anchor": "champion-you"}], "zoom": {"kind": "anchor", "anchor": "champion-you"}, "complete": {"on": "next"}}, {"id": "use-skill", "objective": "Panaudok čempiono galią", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kai kurios galios reikalauja taikinio — korta švytės. Panaudok pirmąją.", "voiceId": "l4-s07", "voiceText": "Kai kurios galios kainuoja aukso. Kai kurios reikalauja taikinio — korta švytės, kol pasirinksi. Panaudok pirmąją galią dabar."}], "highlight": [{"kind": "anchor", "anchor": "champion-you"}], "arrowTo": {"kind": "anchor", "anchor": "champion-you"}, "arrowStyle": "pulse", "allow": [{"kind": "use-champion"}], "wrongHint": "Bakstelėk savo čempioną ir pasirink pirmąjį gebėjimą.", "complete": {"on": "event", "eventType": "ability", "side": "you"}}, {"id": "phase-down", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Ištraukei aukštesnę fazę per anksti? RANKOJE ją gali iškeisti į žemesnę. Lentoje stovinčio — ne.", "voiceId": "l4-s08", "voiceText": "Ir dar viena gudrybė. Ištraukei trečią fazę, o čempiono lentoje dar nėra? Rankoje tą kortą gali iškeisti į žemesnę tos pačios giminės fazę — ji ateina iš kaladės ar kapinyno, kad išvis galėtum jį pašaukti. Bet įsidėmėk: jau stovinčio lentoje čempiono nuleisti žemyn negali. Fazės eina tik aukštyn."}], "complete": {"on": "next"}}, {"id": "finish", "objective": "Užbaik priešą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Čempionas krenta — kova nesibaigia, bet jo netektis skaudi. Užbaik priešą.", "voiceId": "l4-s09", "voiceText": "Čempionas krenta — kova nesibaigia, bet jo netektis skaudi. Saugok jį. Užbaik priešą."}], "allow": [{"kind": "attack-any"}, {"kind": "play-unit"}, {"kind": "use-champion"}, {"kind": "end-turn"}], "complete": {"on": "win"}}, {"id": "victory", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Pergalė! Ravenof tavimi patenkintas.", "voiceId": "sys-victory", "voiceText": "Pergalė! Ravenof tavimi patenkintas."}], "complete": {"on": "next"}}]}$cfg$::jsonb, updated_at = now() where seed_key = 'tut-v3-l4';
update public.tutorial_lessons set config = $cfg${"guideName": "Senasis Korvas", "setup": {"disableZmk": true, "player": {"gold": 1000, "board": ["Ida", "Gisela", "Riteris"], "hand": ["Magmos širdis", "Volkano papėdė", "Aukso kasykla", "Klausas", "Piratas žvalgas"], "deck": ["Piratas žvalgas", "Hokieg’as"]}, "enemy": {"hp": 10, "board": ["Hikage"], "deck": ["Goblinas žvalgas", "Hikage"]}}, "steps": [{"id": "intro", "objective": "Tylios jėgos", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Ne viskas kaunasi. Kai kas... tiesiog stovi ir keičia pasaulį.", "voiceId": "l5-s01", "voiceText": "Ne viskas kaunasi. Kai kas... tiesiog stovi ir keičia pasaulį."}], "complete": {"on": "next"}}, {"id": "artifact", "objective": "Padėk artefaktą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Artefaktai veikia kas ėjimą patys. Bet jie turi gyvybes — priešas gali juos SUDAUŽYTI.", "voiceId": "l5-s02", "voiceText": "Artefaktai gula į savo zoną ir veikia kas ėjimą — patys. Bet įsidėmėk: jie turi gyvybes, ir priešas gali juos sudaužyti. Padėk artefaktą."}], "highlight": [{"kind": "handCard", "cardName": "Magmos širdis"}, {"kind": "anchor", "anchor": "artifacts-you"}], "arrowFrom": {"kind": "handCard", "cardName": "Magmos širdis"}, "arrowTo": {"kind": "anchor", "anchor": "artifacts-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-any", "cardName": "Magmos širdis"}], "complete": {"on": "event", "eventType": "artifact", "side": "you"}}, {"id": "artifact-works", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kiekvieno tavo ėjimo pradžioje jis dirbs tau. Nemokamai.", "voiceId": "l5-s03", "voiceText": "Matai? Kiekvieno tavo ėjimo pradžioje jis dirbs tau. Nemokamai. Amžinai — arba kol stovi."}], "highlight": [{"kind": "anchor", "anchor": "artifacts-you"}], "zoom": {"kind": "anchor", "anchor": "artifacts-you"}, "complete": {"on": "next"}}, {"id": "field", "objective": "Sužaisk lauko kortą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "LAUKO korta keičia patį mūšio lauką. Žaisk ją ir žiūrėk atidžiai.", "voiceId": "l5-s04", "voiceText": "LAUKO korta keičia patį mūšio lauką. Žaisk ją ir žiūrėk atidžiai."}], "highlight": [{"kind": "handCard", "cardName": "Volkano papėdė"}, {"kind": "anchor", "anchor": "field"}], "arrowFrom": {"kind": "handCard", "cardName": "Volkano papėdė"}, "arrowTo": {"kind": "anchor", "anchor": "field"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-any", "cardName": "Volkano papėdė"}], "complete": {"on": "event", "eventType": "field", "side": "you"}}, {"id": "field-both", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Arena pasikeitė. Lauko galia veikia ABU — ir tave.", "voiceId": "l5-s05", "voiceText": "Pati arena pasikeitė... Lauko kortos galia veikia abu žaidėjus. Ir tave. Rinkis lauką, kuris tavo kaladei naudingesnis nei priešo."}], "highlight": [{"kind": "anchor", "anchor": "field"}], "arrowTo": {"kind": "anchor", "anchor": "field"}, "arrowStyle": "pulse", "zoom": {"kind": "anchor", "anchor": "field"}, "complete": {"on": "next"}}, {"id": "field-replace", "objective": "Pakeisk lauką", "apply": {"goldYou": 1000}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Naujas laukas išstumia senąjį. Vienu metu — tik vienas pasaulis.", "voiceId": "l5-s06", "voiceText": "Naujas laukas išstumia senąjį. Vienu metu — tik vienas pasaulis."}], "highlight": [{"kind": "handCard", "cardName": "Aukso kasykla"}, {"kind": "anchor", "anchor": "field"}], "arrowFrom": {"kind": "handCard", "cardName": "Aukso kasykla"}, "arrowTo": {"kind": "anchor", "anchor": "field"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-any", "cardName": "Aukso kasykla"}], "complete": {"on": "event", "eventType": "field", "side": "you"}}, {"id": "aura", "objective": "Iškviesk auros nešėją", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "AUROS: padaras stiprina savus vien BŪDAMAS lentoje (šis – Provokacijos padarus). Aura dingsta kartu su nešėju.", "voiceId": "l5-s07", "voiceText": "Dar viena tyli jėga — auros. Kai kurie padarai vien būdami lentoje stiprina savus... ar nuodija priešus. Aura dingsta kartu su nešėju — todėl auros nešėjai visada pirmi taikiniai."}], "highlight": [{"kind": "handCard", "cardName": "Klausas"}], "arrowFrom": {"kind": "handCard", "cardName": "Klausas"}, "arrowTo": {"kind": "anchor", "anchor": "units-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-unit", "cardName": "Klausas"}], "complete": {"on": "event", "eventType": "play", "side": "you", "cardName": "Klausas"}}, {"id": "aura-see", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Puiku. Pažvelk — riterio skaičiai paaugo.", "voiceId": "sys-good-1", "voiceText": "Puiku."}], "highlight": [{"kind": "anchor", "anchor": "units-you"}], "zoom": {"kind": "anchor", "anchor": "units-you"}, "complete": {"on": "next"}}, {"id": "finish", "objective": "Užbaik priešą", "allow": [{"kind": "attack-any"}, {"kind": "play-unit"}, {"kind": "play-spell"}, {"kind": "end-turn"}], "complete": {"on": "win"}}, {"id": "victory", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Pergalė! Ravenof tavimi patenkintas.", "voiceId": "sys-victory", "voiceText": "Pergalė! Ravenof tavimi patenkintas."}], "complete": {"on": "next"}}]}$cfg$::jsonb, updated_at = now() where seed_key = 'tut-v3-l5';
update public.tutorial_lessons set config = $cfg${"guideName": "Senasis Korvas", "setup": {"disableZmk": true, "player": {"gold": 1000, "board": ["Gisela"], "hand": ["Ledo spindulys", "Takumi", "Matriarchė Gorta", "Liepsnos antspaudas", "Nakties tarnas"], "deck": ["Piratas žvalgas", "Ida", "Impas", "Hokieg’as"]}, "enemy": {"hp": 40, "board": ["Wrosxa"], "deck": ["Hikage", "Goblinas žvalgas", "Zombis klajoklis"]}}, "steps": [{"id": "intro", "objective": "Skaityk ženklus ant kortų", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Būsenos laimi kovas dažniau nei kardai.", "voiceId": "l6-s01", "voiceText": "Šiandien išmoksi skaityti ženklus ant kortų. Būsenos. Jos laimi kovas dažniau nei kardai."}], "complete": {"on": "next"}}, {"id": "freeze-cast", "objective": "Užšaldyk priešą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "ŠALTIS: užšaldytas padaras NEATSAKO į smūgius. Užšaldyk priešą.", "voiceId": "l6-s02", "voiceText": "Šaltis. Užšaldytas padaras neatsako į smūgius. Pulk jį — jis tylės. Ledo magai tuo ir gyvena."}], "highlight": [{"kind": "handCard", "cardName": "Ledo spindulys"}, {"kind": "unit", "side": "ai", "cardName": "Wrosxa"}], "arrowFrom": {"kind": "handCard", "cardName": "Ledo spindulys"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Wrosxa"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-spell", "cardName": "Ledo spindulys"}], "complete": {"on": "event", "eventType": "spell", "side": "you", "cardName": "Ledo spindulys"}}, {"id": "freeze-attack", "objective": "Pulk užšaldytą — be atsako", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Dabar pulk jį. Atsakomojo smūgio nebus.", "voiceId": "sys-good-3", "voiceText": "Gerai, mokiny."}], "highlight": [{"kind": "unit", "side": "you", "cardName": "Gisela"}, {"kind": "unit", "side": "ai", "cardName": "Wrosxa"}], "arrowFrom": {"kind": "unit", "side": "you", "cardName": "Gisela"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Wrosxa"}, "arrowStyle": "drag-path", "allow": [{"kind": "attack-unit", "targetName": "Wrosxa"}], "complete": {"on": "event", "eventType": "attack", "side": "you"}}, {"id": "stun", "objective": "Apsvaigink priešą", "apply": {"addBoardAi": ["Hikage"], "goldYou": 1000}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "APSVAIGIMAS: padaras praleidžia savo ėjimą. Iškviesk kovotoją ir nurodyk taikinį.", "voiceId": "l6-s03", "voiceText": "Apsvaigimas. Apsvaigintas padaras praleidžia savo ėjimą — nei puola, nei ginasi protingai. Nukalk jo sargą, kol miega."}], "highlight": [{"kind": "handCard", "cardName": "Takumi"}, {"kind": "unit", "side": "ai", "cardName": "Hikage"}], "arrowFrom": {"kind": "handCard", "cardName": "Takumi"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Hikage"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-unit", "cardName": "Takumi"}], "complete": {"on": "event", "eventType": "play", "side": "you", "cardName": "Takumi"}}, {"id": "poison", "objective": "Apnuodyk", "apply": {"goldYou": 1000}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "NUODAI: žala kas ėjimą IR nepalankios atakos — traukiamos dvi likimo kortos, galioja blogesnė.", "voiceId": "l6-s04", "voiceText": "Nuodai ir ugnis ėda gyvybes kas ėjimą, po truputį. Bet nuodai kerta dukart: apnuodytas padaras dar ir puola nepalankiai — jam traukiamos dvi likimo kortos, o galioja blogesnė. Lėta mirtis — bet mirtis."}], "highlight": [{"kind": "handCard", "cardName": "Matriarchė Gorta"}], "arrowFrom": {"kind": "handCard", "cardName": "Matriarchė Gorta"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Hikage"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-unit", "cardName": "Matriarchė Gorta"}], "complete": {"on": "event", "eventType": "play", "side": "you", "cardName": "Matriarchė Gorta"}}, {"id": "burn", "objective": "Padek", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "O dabar — ugnis.", "voiceId": "sys-good-2", "voiceText": "Būtent taip."}], "highlight": [{"kind": "handCard", "cardName": "Liepsnos antspaudas"}], "arrowFrom": {"kind": "handCard", "cardName": "Liepsnos antspaudas"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Wrosxa"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-spell", "cardName": "Liepsnos antspaudas"}], "complete": {"on": "event", "eventType": "spell", "side": "you", "cardName": "Liepsnos antspaudas"}}, {"id": "shield-stealth", "objective": "Skydas ir sėlinimas", "apply": {"clearBoardYou": true, "addBoardYou": ["Gisela", "Ordino pėstininkas", "Toguchi"]}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "SKYDAS sugeria vieną smūgį pilnai. SĖLINIMAS slepia padarą, kol jis pats nesmogia.", "voiceId": "l6-s06", "voiceText": "Skydas sugeria vieną smūgį pilnai. Sėlinimas slepia padarą nuo taikymosi, kol jis pats nesmogia."}], "highlight": [{"kind": "unit", "side": "you", "cardName": "Ordino pėstininkas"}, {"kind": "unit", "side": "you", "cardName": "Toguchi"}], "zoom": {"kind": "unit", "side": "you", "cardName": "Ordino pėstininkas"}, "complete": {"on": "next"}}, {"id": "taunt", "objective": "Provokacija — siena", "apply": {"addBoardAi": ["Gorgonės golemas"]}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "PROVOKACIJA: kol jis lentoje — privalai pulti JĮ pirmiausia.", "voiceId": "l6-s07", "voiceText": "Ir provokacija. Kol lentoje stovi provokuojantis padaras — privalai pulti jį pirmiausia. Jis — siena. Statyk sienas savo silpniems, griauk priešo sienas pirmas."}], "highlight": [{"kind": "unit", "side": "ai", "cardName": "Gorgonės golemas"}], "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Gorgonės golemas"}, "arrowStyle": "pulse", "zoom": {"kind": "unit", "side": "ai", "cardName": "Gorgonės golemas"}, "complete": {"on": "next"}}, {"id": "silence", "objective": "Nutildyk sieną", "apply": {"goldYou": 1000}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "NUTILDYMAS nuima nuo kortos VISKĄ — net Provokaciją. Iškviesk tarną ir nutildyk golemą.", "voiceId": "l6-s05", "voiceText": "Nutildymas. Baisiausias iš visų. Nuima nuo kortos viską — tekstą, buffus, galias. Lieka tik kūnas ir skaičiai. Prieš galingą efektą — nutildymas."}], "highlight": [{"kind": "handCard", "cardName": "Nakties tarnas"}, {"kind": "unit", "side": "ai", "cardName": "Gorgonės golemas"}], "arrowFrom": {"kind": "handCard", "cardName": "Nakties tarnas"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Gorgonės golemas"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-unit", "cardName": "Nakties tarnas"}], "complete": {"on": "event", "eventType": "play", "side": "you", "cardName": "Nakties tarnas"}}, {"id": "sprint-play", "objective": "Sprintas: pulk tą patį ėjimą", "apply": {"addHandYou": ["Tsurano"], "goldYou": 1000}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "SPRINTAS leidžia pulti tą patį ėjimą — jokios iškvietimo ligos.", "voiceId": "l6-s08", "voiceText": "Sprintas leidžia pulti tą patį ėjimą, kai iškviestas — jokios iškvietimo ligos. Greitis kainuoja, bet stebina."}], "highlight": [{"kind": "handCard", "cardName": "Tsurano"}], "arrowFrom": {"kind": "handCard", "cardName": "Tsurano"}, "arrowTo": {"kind": "anchor", "anchor": "units-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-unit", "cardName": "Tsurano"}], "complete": {"on": "event", "eventType": "play", "side": "you", "cardName": "Tsurano"}}, {"id": "sprint-attack", "objective": "Pulk iškart", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "O dabar — pulk juo iškart.", "voiceId": "sys-good-1", "voiceText": "Puiku."}], "highlight": [{"kind": "unit", "side": "you", "cardName": "Tsurano"}], "arrowFrom": {"kind": "unit", "side": "you", "cardName": "Tsurano"}, "arrowTo": {"kind": "anchor", "anchor": "units-ai"}, "arrowStyle": "drag-path", "allow": [{"kind": "attack-any"}], "complete": {"on": "event", "eventType": "attack", "side": "you"}}, {"id": "blessed", "objective": "Palaiminimas: kitas smūgis su pranašumu", "apply": {"enableZmk": true, "goldYou": 1000, "clearBoardYou": true, "addBoardYou": ["Gisela", "Ida"], "addBoardAi": ["Zombis klajoklis"], "setStatus": [{"side": "you", "cardName": "Ida", "status": "blessed"}]}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "PALAIMINIMAS: kitas to padaro smūgis traukiamas su PRANAŠUMU — dvi likimo kortos, galioja geresnė.", "voiceId": "l6-s09", "voiceText": "Ir šviesioji pusė — palaiminimas. Kitas to padaro smūgis traukiamas su pranašumu: likimas ištraukia dvi kortas, o galioja geresnė. Vienkartinis, bet dažnai lemiamas. Pulk juo ir pažiūrėk pats."}], "highlight": [{"kind": "unit", "side": "you", "cardName": "Ida"}], "arrowFrom": {"kind": "unit", "side": "you", "cardName": "Ida"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Zombis klajoklis"}, "arrowStyle": "drag-path", "allow": [{"kind": "attack-any"}], "complete": {"on": "event", "eventType": "attack", "side": "you"}}, {"id": "battlecry", "objective": "Kovos šūksnis: efektas iškviečiant", "apply": {"addHandYou": ["Šerkšnadūmis"], "goldYou": 1000}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "KOVOS ŠŪKSNIS suveikia TĄ AKIMIRKĄ, kai padaras iškviečiamas. Vieną kartą — bet iškart.", "voiceId": "l6-s10", "voiceText": "Kovos šūksnis. Toks padaras smogia dar nespėjęs įsitvirtinti: efektas suveikia tą akimirką, kai jis iškviečiamas iš rankos. Vieną kartą — bet iškart, ir priešas nespėja pasiruošti. Iškviesk jį ir nurodyk taikinį."}], "highlight": [{"kind": "handCard", "cardName": "Šerkšnadūmis"}], "arrowFrom": {"kind": "handCard", "cardName": "Šerkšnadūmis"}, "arrowTo": {"kind": "anchor", "anchor": "units-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-unit", "cardName": "Šerkšnadūmis"}], "complete": {"on": "event", "eventType": "play", "side": "you", "cardName": "Šerkšnadūmis"}}, {"id": "lastwish", "objective": "Paskutinis noras: efektas žūstant", "apply": {"addBoardYou": ["Impas"], "addBoardAi": ["Wrosxa"]}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "PASKUTINIS NORAS suveikia ŽŪSTANT. Pulk stipresnį — ir pamatysi, ką jis palieka.", "voiceId": "l6-s11", "voiceText": "O paskutinis noras — priešingybė: jis suveikia tada, kai padaras žūsta. Todėl tokį padarą nužudyti kartais brangiau, nei palikti gyvą. Pulk juo stipresnį priešą ir pažiūrėk, ką jis tau paliks krisdamas."}], "highlight": [{"kind": "unit", "side": "you", "cardName": "Impas"}], "arrowFrom": {"kind": "unit", "side": "you", "cardName": "Impas"}, "arrowTo": {"kind": "unit", "side": "ai", "cardName": "Wrosxa"}, "arrowStyle": "drag-path", "allow": [{"kind": "attack-any"}], "wrongHint": "Pulk paryškintu skydnešiu — jis turi žūti, kad pamatytum Paskutinį norą.", "complete": {"on": "event", "eventType": "lastwish", "side": "you"}}, {"id": "outro", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Ženklus skaityti išmokai. Toliau — tamsioji pusė.", "voiceId": "sys-good-3", "voiceText": "Gerai, mokiny."}], "complete": {"on": "next"}}]}$cfg$::jsonb, updated_at = now() where seed_key = 'tut-v3-l6';
update public.tutorial_lessons set config = $cfg${"guideName": "Senasis Korvas", "setup": {"disableZmk": true, "player": {"gold": 600, "board": ["Ida"], "hand": ["Digolan’as", "Gniuždantis žvilgsnis"], "deck": ["Piratas žvalgas", "Gisela", "Hokieg’as"], "curses": ["Kraujo duoklė", "Šnabždėjimas po oda", "Pragaro sutartis"]}, "enemy": {"hp": 30, "board": ["Hikage"], "deck": ["Goblinas žvalgas", "Hikage", "Zombis klajoklis"]}}, "steps": [{"id": "intro", "objective": "Tamsioji pusė", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Dabar... tamsioji pusė. Demonų menas. Prakeiksmai.", "voiceId": "l7-s01", "voiceText": "Dabar... tamsioji pusė. Demonų menas. Prakeiksmai."}], "complete": {"on": "next"}}, {"id": "side-deck", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Demonų kaladė turi ŠEŠĖLĮ — šoninę prakeiksmų kaladę (iki 20).", "voiceId": "l7-s02", "voiceText": "Demonų kaladė turi šešėlį — šoninę prakeiksmų kaladę. Iki dvidešimties. Jie ne tavo rankoje — jie laukia savo valandos šalia."}], "highlight": [{"kind": "anchor", "anchor": "deck-you"}], "arrowTo": {"kind": "anchor", "anchor": "deck-you"}, "arrowStyle": "pulse", "zoom": {"kind": "anchor", "anchor": "deck-you"}, "complete": {"on": "next"}}, {"id": "inject", "objective": "Įmaišyk prakeiksmus į priešo kaladę", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Demonų efektai ĮMAIŠO prakeiksmus į PRIEŠO kaladę. Žiūrėk.", "voiceId": "l7-s03", "voiceText": "Demonų efektai įmaišo prakeiksmus į priešo kaladę. Žiūrėk — štai jis, šliaužia į svetimą kaladę..."}], "highlight": [{"kind": "handCard", "cardName": "Digolan’as"}, {"kind": "anchor", "anchor": "deck-ai"}], "arrowFrom": {"kind": "handCard", "cardName": "Digolan’as"}, "arrowTo": {"kind": "anchor", "anchor": "units-you"}, "arrowStyle": "drag-path", "allow": [{"kind": "play-unit", "cardName": "Digolan’as"}], "complete": {"on": "event", "eventType": "play", "side": "you", "cardName": "Digolan’as"}}, {"id": "inject-explain", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Priešas trauks kortas... ir vieną dieną ištrauks TAVO prakeiksmą.", "voiceId": "l7-s04", "voiceText": "O dabar gražiausia. Priešas trauks kortas... ir vieną dieną ištrauks tavo prakeiksmą. Tada jis suveiks. Jo rankoje. Jo ėjime."}], "complete": {"on": "next"}}, {"id": "end-turn", "objective": "Baik ėjimą — tegul traukia", "apply": {"seedEnemyDeckTop": ["Kraujo duoklė"]}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Baik ėjimą. Priešo ėjimas — stebėk jo kaladę.", "voiceId": "sys-turn-enemy", "voiceText": "Priešo ėjimas. Stebėk."}], "highlight": [{"kind": "button", "id": "end-turn"}], "arrowTo": {"kind": "button", "id": "end-turn"}, "arrowStyle": "pulse", "allow": [{"kind": "end-turn"}], "complete": {"on": "event", "eventType": "endTurn", "side": "you"}}, {"id": "curse-fires", "enemyScript": [{"type": "endTurn"}], "complete": {"on": "enemyTurnDone"}}, {"id": "curse-explain", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Štai! Priešas net kortos negavo — vien skausmą.", "voiceId": "l7-s05", "voiceText": "Štai! Girdi? Tai prakeiksmo balsas. Priešas net kortos negavo — vien skausmą."}], "highlight": [{"kind": "anchor", "anchor": "hp-ai"}], "zoom": {"kind": "anchor", "anchor": "hp-ai"}, "complete": {"on": "next"}}, {"id": "outro", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Demonų meistrai stato kaladas aplink tai. Tamsi simfonija.", "voiceId": "l7-s06", "voiceText": "Demonų meistrai stato kaladas aplink tai: vieni efektai maišo prakeiksmus, kiti stiprėja jiems suveikus, treti baudžia priešą už kiekvieną ištrauktą kortą. Tamsi simfonija."}], "complete": {"on": "next"}}]}$cfg$::jsonb, updated_at = now() where seed_key = 'tut-v3-l7';
update public.tutorial_lessons set config = $cfg${"guideName": "Senasis Korvas", "matchStartFlow": true, "setup": {"disableZmk": true, "player": {"hand": ["Piratas žvalgas", "Tornadas", "Ida", "Užnugario ataka", "Hokieg’as"], "deck": ["Gisela", "Piratas žvalgas", "Ida"]}, "enemy": {"hp": 30, "board": ["Hikage"], "deck": ["Goblinas žvalgas", "Hikage", "Zombis klajoklis"]}}, "steps": [{"id": "intro", "objective": "Kas vyksta prieš kovą", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Paskutinė pamoka — apie tai, kas vyksta PRIEŠ kovą ir kas laukia jos gale.", "voiceId": "l8-s01", "voiceText": "Paskutinė pamoka — apie tai, kas vyksta PRIEŠ kovą ir kas laukia jos gale."}], "complete": {"on": "next"}}, {"id": "coin", "objective": "Likimas renkasi, kas pradeda", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kiekviena kova prasideda monetos metimu. Žalia — tu, raudona — priešas.", "voiceId": "l8-s02", "voiceText": "Kiekviena tikra kova prasideda monetos metimu. Likimas renkasi, kas eina pirmas. Žalia — tu. Raudona — priešas."}], "highlight": [{"kind": "anchor", "anchor": "coin"}], "arrowTo": {"kind": "anchor", "anchor": "coin"}, "arrowStyle": "pulse", "zoom": {"kind": "anchor", "anchor": "coin"}, "complete": {"on": "next"}}, {"id": "mulligan", "objective": "Pakeisk brangias pradines kortas", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Pirmoji ranka: pažymėk kortas, kurias nori keisti. Brangios kortos pradžioje — balastas.", "voiceId": "l8-s03", "voiceText": "Dabar — pirmoji ranka. Netinka? Pažymėk kortas, kurias nori keisti — jos grįš į kaladę, gausi naujas. Patarimas: brangios kortos pradžioje — balastas. Keisk jas."}], "highlight": [{"kind": "handCard", "cardName": "Tornadas"}], "arrowTo": {"kind": "handCard", "cardName": "Tornadas"}, "arrowStyle": "pulse", "zoom": {"kind": "handCard", "cardName": "Tornadas"}, "allow": [{"kind": "mulligan"}], "wrongHint": "Pažymėk brangias kortas ir patvirtink apačioje.", "complete": {"on": "mulliganDone"}}, {"id": "cost-rule", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Pirmais ėjimais teturėsi šimtą ar du. Ranka pilna brangenybių — ranka tuščia darbų.", "voiceId": "l8-s04", "voiceText": "Prisimink kainos taisyklę: pirmais ėjimais teturėsi šimtą ar du. Ranka pilna brangenybių — ranka tuščia darbų."}], "highlight": [{"kind": "anchor", "anchor": "gold"}], "zoom": {"kind": "anchor", "anchor": "gold"}, "complete": {"on": "next"}}, {"id": "sell", "objective": "Parduok kortą už +100", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kartą per ėjimą gali PARDUOTI kortą iš rankos už 100 aukso. Pabandyk.", "voiceId": "l8-s05", "voiceText": "Užmiršau paminėti dar vieną monetą. Kartą per ėjimą gali parduoti kortą iš rankos už šimtą aukso. Nereikalinga korta virsta ankstyvu padaru. Meistrų triukas."}], "highlight": [{"kind": "button", "id": "discard-gold"}], "arrowTo": {"kind": "button", "id": "discard-gold"}, "arrowStyle": "pulse", "allow": [{"kind": "discard-gold"}], "wrongHint": "Spausk „Parduoti kortą\" ir pažymėk nereikalingą kortą rankoje.", "complete": {"on": "event", "eventType": "discardGold", "side": "you"}}, {"id": "fatigue-setup", "objective": "Baik ėjimą — pažiūrėsim į NUOVARGĮ", "apply": {"deckCountYou": 0}, "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Kai kaladė tuščia, o traukti privalai — NUOVARGIS: 1, paskui 2, paskui 3 žalos.", "voiceId": "l8-s06", "voiceText": "Ir pabaiga, apie kurią žadėjau papasakoti. Kai kaladė ištuštėja, o tu privalai traukti — nuovargis. Pirmas tuščias traukimas — vienas skausmo. Antras — du. Trečias — trys... Ilga kova visada baigiasi — vienaip ar kitaip."}], "highlight": [{"kind": "anchor", "anchor": "deck-you"}], "arrowTo": {"kind": "button", "id": "end-turn"}, "arrowStyle": "pulse", "allow": [{"kind": "end-turn"}], "complete": {"on": "event", "eventType": "endTurn", "side": "you"}}, {"id": "fatigue-show", "enemyScript": [{"type": "attack", "attackerCard": "Hikage", "face": true}, {"type": "endTurn"}], "complete": {"on": "enemyTurnDone"}}, {"id": "hand-limit", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Rankoje telpa dešimt kortų. Vienuolikta sudegtų.", "voiceId": "l8-s07", "voiceText": "Dar žinok: rankoje telpa dešimt kortų. Vienuolikta sudegtų. Netaupyk to, ko negali panešti."}], "highlight": [{"kind": "anchor", "anchor": "hand"}], "complete": {"on": "next"}}, {"id": "farewell", "dialogue": [{"speaker": "guide", "name": "Senasis Korvas", "text": "Tai viskas, ką galiu duoti žodžiais. Likusio išmokys pralaimėjimai. Eik.", "voiceId": "l8-s08", "voiceText": "Tai viskas, ką galiu tau duoti žodžiais, mokiny. Likusio išmokys pralaimėjimai — jie geriausi mokytojai Ravenof'e. Eik. Kaunu tavimi didžiuotis."}], "complete": {"on": "next"}}]}$cfg$::jsonb, updated_at = now() where seed_key = 'tut-v3-l8';

